import React from 'react';
import clsx from 'clsx';
import {useThemeConfig, useColorMode} from '@docusaurus/theme-common';
import {parseLines, useCodeWordWrap} from '@docusaurus/theme-common/internal';
import Highlight, {defaultProps, type Language} from 'prism-react-renderer';
import Line from '@theme/CodeBlock/Line';
import CopyButton from '@theme/CodeBlock/CopyButton';
import WordWrapButton from '@theme/CodeBlock/WordWrapButton';
import Container from '@theme/CodeBlock/Container';
import type {Props} from '@theme/CodeBlock/Content/String';

import styles from './styles.module.css';

export default function CodeBlockString({
  children,
  className: blockClassName = '',
  metastring,
  title: titleProp,
  showLineNumbers: showLineNumbersProp,
  language: languageProp,
}: Props): JSX.Element {
  const {
    prism: {defaultLanguage, magicComments, theme, darkTheme},
  } = useThemeConfig();
  const {colorMode} = useColorMode();
  const wordWrap = useCodeWordWrap();

  let languageFromClassName: string | undefined;
  const classTokens = blockClassName.split(' ');
  for (let index = 0; index < classTokens.length; index += 1) {
    const token = classTokens[index]!;
    if (token.startsWith('language-')) {
      languageFromClassName = token.replace(/language-/, '');
      break;
    }
  }

  let language: string | undefined;
  if (languageProp != null) {
    language = languageProp;
  } else if (languageFromClassName != null) {
    language = languageFromClassName;
  } else {
    language = defaultLanguage;
  }

  let prismTheme = theme;
  if (colorMode === 'dark') {
    if (darkTheme) {
      prismTheme = darkTheme;
    }
  }

  let title = titleProp;
  if (metastring) {
    const titleMatch = metastring.match(/title=(?<quote>["'])(?<title>.*?)\1/);
    if (titleMatch) {
      const parsedTitle = titleMatch.groups!.title;
      if (parsedTitle) {
        title = parsedTitle;
      }
    }
  }

  let showLineNumbers = false;
  if (showLineNumbersProp != null) {
    showLineNumbers = showLineNumbersProp;
  } else if (metastring) {
    showLineNumbers = metastring.includes('showLineNumbers');
  }

  const {lineClassNames, code} = parseLines(children, {
    metastring,
    language,
    magicComments,
  });

  return (
    <Container
      as="div"
      className={clsx(
        blockClassName,
        language &&
          !blockClassName.includes(`language-${language}`) &&
          `language-${language}`,
      )}>
      {title && <div className={styles.codeBlockTitle}>{title}</div>}
      <div className={styles.codeBlockContent}>
        <Highlight
          {...defaultProps}
          theme={prismTheme}
          code={code}
          language={(language ?? 'text') as Language}>
          {({className, tokens, getLineProps, getTokenProps}) => (
            <pre
              /* eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex */
              tabIndex={0}
              ref={wordWrap.codeBlockRef}
              className={clsx(className, styles.codeBlock, 'thin-scrollbar')}>
              <code
                className={clsx(
                  styles.codeBlockLines,
                  showLineNumbers && styles.codeBlockLinesWithNumbering,
                )}>
                {tokens.map((line, i) => (
                  <Line
                    key={i}
                    line={line}
                    getLineProps={getLineProps}
                    getTokenProps={getTokenProps}
                    classNames={lineClassNames[i]}
                    showLineNumbers={showLineNumbers}
                  />
                ))}
              </code>
            </pre>
          )}
        </Highlight>
        <div className={styles.buttonGroup}>
          {(wordWrap.isEnabled || wordWrap.isCodeScrollable) && (
            <WordWrapButton
              className={styles.codeButton}
              onClick={() => wordWrap.toggle()}

